function renderTabBar(active: TabKey, onSelect: (tab: TabKey) => void): JSX.Element {
  return {
    type: 'nav',
    props: {
      className: 'tab-bar',
      role: 'tablist',
      'aria-label': 'Primary',
      style: {
        display: 'flex',
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'stretch',
        position: 'sticky',
        bottom: 0,
        width: '100%',
        minWidth: '360px',
        maxWidth: '430px',
        margin: '0 auto',
        boxSizing: 'border-box'
